import _toConsumableArray from "@babel/runtime/helpers/toConsumableArray";
import get from 'lodash/get';
import sortBy from 'lodash/sortBy';
import uniq from 'lodash/uniq';
import { useMemo } from 'react';
import CozyClient, { Q, useQuery, hasQueryBeenLoaded } from 'cozy-client';

var useFolderToSaveFiles = function useFolderToSaveFiles(folderToSaveId) {
  return useQuery(Q('io.cozy.files').where({
    dir_id: folderToSaveId,
    trashed: false
  }).indexFields(['dir_id', 'cozyMetadata.createdAt']).sortBy([{
    dir_id: 'desc'
  }, {
    'cozyMetadata.createdAt': 'desc'
  }]).limitBy(5), {
    as: "fileDataCard_io.cozy.files/".concat(folderToSaveId, "/io.cozy.files"),
    fetchPolicy: CozyClient.fetchPolicies.olderThan(30 * 1000)
  });
};

var useSourceAccountIdentifierFiles = function useSourceAccountIdentifierFiles(sourceAccountIdentifier, slug) {
  return useQuery(Q('io.cozy.files').where({
    'cozyMetadata.sourceAccountIdentifier': sourceAccountIdentifier,
    'cozyMetadata.createdByApp': slug,
    trashed: false
  }).indexFields(['cozyMetadata.sourceAccountIdentifier', 'cozyMetadata.createdAt', 'cozyMetadata.createdByApp', 'trashed']).sortBy([{
    'cozyMetadata.sourceAccountIdentifier': 'desc'
  }, {
    'cozyMetadata.createdAt': 'desc'
  }, {
    'cozyMetadata.createdByApp': 'desc'
  }, {
    trashed: 'desc'
  }]).limitBy(5), {
    as: "fileDataCard_io.cozy.files/sourceAccountIdentifier/".concat(sourceAccountIdentifier, "/createdByApp/").concat(slug),
    fetchPolicy: CozyClient.fetchPolicies.olderThan(30 * 1000)
  });
};

var getResponse = function getResponse(folderToSaveFiles, sourceAccountIdentifierFiles) {
  var loaded = Boolean(hasQueryBeenLoaded(folderToSaveFiles) && hasQueryBeenLoaded(sourceAccountIdentifierFiles));
  if (folderToSaveFiles.fetchStatus === 'failed' && sourceAccountIdentifierFiles === 'failed') return {
    fetchStatus: 'failed'
  };
  if (loaded && folderToSaveFiles.data.length === 0 && sourceAccountIdentifierFiles.data.length === 0) return {
    fetchStatus: 'empty'
  };
  if (loaded) return {
    data: sortBy(uniq([].concat(_toConsumableArray(folderToSaveFiles.data), _toConsumableArray(sourceAccountIdentifierFiles.data)), function (x) {
      return x._id;
    }), function (x) {
      return get(x, 'cozyMetadata.createdAt');
    }).reverse().slice(0, 5),
    fetchStatus: 'loaded'
  };
  return {
    fetchStatus: 'loading'
  };
};

export var useDataCardFiles = function useDataCardFiles(sourceAccountIdentifier, folderToSaveId, slug) {
  if (!sourceAccountIdentifier || !folderToSaveId) throw new Error('Missing arguments in useDataCardFiles, cannot fetch files');
  var folderToSaveFiles = useFolderToSaveFiles(folderToSaveId);
  var sourceAccountIdentifierFiles = useSourceAccountIdentifierFiles(sourceAccountIdentifier, slug);
  return useMemo(function () {
    return getResponse(folderToSaveFiles, sourceAccountIdentifierFiles);
  }, [folderToSaveFiles, sourceAccountIdentifierFiles]);
};